describe('Form Validation - Submit Button Disabled Until Required Fields Filled', () => {
  beforeEach(() => {
    cy.visit('/form');
    cy.get('form').should('be.visible');
  });

  it('should have submit button disabled when form loads with empty required fields', () => {
    cy.get('button[type="submit"]').should('be.disabled');
  });

  it('should enable submit button only when all required fields are filled', () => {
    const requiredFields = [
      { selector: 'input[name="firstName"]', value: 'John' },
      { selector: 'input[name="lastName"]', value: 'Doe' },
      { selector: 'input[name="email"]', value: 'john@example.com' },
      { selector: 'textarea[name="message"]', value: 'Test message' }
    ];

    cy.get('button[type="submit"]').should('be.disabled');

    requiredFields.forEach((field, index) => {
      cy.get(field.selector).type(field.value);

      if (index < requiredFields.length - 1) {
        cy.get('button[type="submit"]').should('be.disabled');
      }
    });

    cy.get('button[type="submit"]').should('not.be.disabled');
  });

  it('should disable submit button again when a required field is cleared', () => {
    cy.get('input[name="firstName"]').type('John');
    cy.get('input[name="lastName"]').type('Doe');
    cy.get('input[name="email"]').type('john@example.com');
    cy.get('textarea[name="message"]').type('Test message');

    cy.get('button[type="submit"]').should('not.be.disabled');

    cy.get('input[name="firstName"]').clear();

    cy.get('button[type="submit"]').should('be.disabled');
  });

  it('should handle edge case with whitespace-only input in required field', () => {
    cy.get('input[name="firstName"]').type('   ');
    cy.get('input[name="lastName"]').type('Doe');
    cy.get('input[name="email"]').type('john@example.com');
    cy.get('textarea[name="message"]').type('Test message');

    cy.get('button[type="submit"]').should('be.disabled');
  });

  it('should enable submit button when all fields including optional ones are filled', () => {
    cy.get('input[name="firstName"]').type('John');
    cy.get('input[name="lastName"]').type('Doe');
    cy.get('input[name="email"]').type('john@example.com');
    cy.get('textarea[name="message"]').type('Test message');
    cy.get('input[name="phone"]').type('1234567890');

    cy.get('button[type="submit"]').should('not.be.disabled');
  });

  it('should validate email format and keep submit button disabled for invalid email', () => {
    cy.get('input[name="firstName"]').type('John');
    cy.get('input[name="lastName"]').type('Doe');
    cy.get('input[name="email"]').type('invalid-email');
    cy.get('textarea[name="message"]').type('Test message');

    cy.get('button[type="submit"]').should('be.disabled');

    cy.get('input[name="email"]').clear().type('john@example.com');

    cy.get('button[type="submit"]').should('not.be.disabled');
  });
});
